import { useEffect, useMemo, useRef, useState } from "react";
import { useLocation } from "wouter";
import { Archive, ArrowLeft, ArrowRight, Check, ChevronDown, CircleAlert, Crop, Edit3, Eye, FolderCog, ImageIcon, LoaderCircle, Package, Plus, Search, SlidersHorizontal, Trash2, UploadCloud, Video, X } from "lucide-react";
import { AppShell } from "@/components/AppShell";
import { AdminPagePanel } from "@/components/AdminPagePanel";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Dialog } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { CategoryManagerV2 } from "@/components/CategoryManager";
import { EasyImageCropper } from "@/components/EasyImageCropper";
import { ProductCatalogFields } from "@/components/ProductCatalogFields";
import { ContextualSaveBar, useContextualSaveVisibility } from "@/components/ContextualSaveBar";
import { api } from "@/lib/api";
import { maybeCelebrateCreation } from "@/lib/creation-celebration";
