import { cn } from "@/lib/utils";
import { centsToCurrencyInput, currencyInputToCents, formatCurrencyInput } from "@/lib/input-formatters";
import { dateRangeFromInputs, formatAdminCurrency, formatAdminDate } from "@/lib/admin-value-formatters";
import { toast } from "sonner";

const PAGE_SIZES = [10, 20, 50, 100];
const emptyFilters = { search: "", dateFrom: "", dateTo: "", page: 1, limit: 20, sort: "recent" };

export default function ProductsPage() { return <AppShell><ProductsContent /></AppShell>; }

export function ProductsContent() {
  const { store } = useActiveStore();
  const [location, navigate] = useLocation();
  const route = productRoute(location);
  const [filters, setFilters] = useState(emptyFilters);
  const [result, setResult] = useState({ data: [], pagination: { page: 1, limit: 20, total: 0, totalPages: 1 } });
  const [loading, setLoading] = useState(true);
  const [categories, setCategories] = useState([]);
  const [categoriesOpen, setCategoriesOpen] = useState(false);
  const [productDialog, setProductDialog] = useState({ open: false, product: null });
  const [productPreview, setProductPreview] = useState(null);
  const [productToDelete, setProductToDelete] = useState(null);
  const [filtersOpen, setFiltersOpen] = useState(false);

  const loadCategories = async () => { if (!store?.id) return; const response = await api.getCategories(store.id); setCategories(response.categories); };
  const loadProducts = async (nextFilters = filters) => {
    if (!store?.id) { setLoading(false); return; }
    setLoading(true);
    try { setResult(await api.getProducts(store.id, normalizeFilters(nextFilters))); } catch (error) { toast.error(error.message); } finally { setLoading(false); }
  };
  useEffect(() => { loadCategories().catch((error) => toast.error(error.message)); }, [store?.id]);
  useEffect(() => { const timeout = window.setTimeout(() => loadProducts(), filters.search ? 280 : 0); return () => window.clearTimeout(timeout); }, [store?.id, filters]);
  useEffect(() => {
    if (!store?.id) return;
    if (route.kind === "create") { setProductPreview(null); setProductDialog({ open: true, product: null }); return; }
    if (route.kind === "edit") {
      setProductPreview(null);
      api.getProduct(store.id, route.productId).then((response) => setProductDialog({ open: true, product: response.product })).catch((error) => { toast.error(error.message); navigate("/products"); });
      return;
    }
    if (route.kind === "view") {
      setProductDialog({ open: false, product: null });
      api.getProduct(store.id, route.productId).then((response) => setProductPreview(response.product)).catch((error) => { toast.error(error.message); navigate("/products"); });
      return;
    }
    setProductDialog({ open: false, product: null });
    setProductPreview(null);
  }, [store?.id, route.key]);
  const changeFilters = (patch) => setFilters((current) => ({ ...current, ...patch, page: patch.page ?? 1 }));
  const refreshAll = async () => { await Promise.all([loadCategories(), loadProducts()]); };
  const openEdit = (id) => navigate(`/products/${id}/edit`);
  const openPreview = (id) => navigate(`/products/${id}`);
  const removeProduct = async () => { if (!productToDelete) return; try { await api.deleteProduct(store.id, productToDelete.id); toast.success("Produto excluído."); setProductToDelete(null); await loadProducts(); } catch (error) { toast.error(error.message); } };
  if (route.kind === "categories" && store?.id) return <CategoryManagerV2 page route={route} onOpenChange={() => navigate("/products")} onNavigate={navigate} storeId={store.id} categories={categories} onUpdated={refreshAll} />;
  if (store?.id && ["create", "edit", "view"].includes(route.kind)) return <AdminPagePanel title={route.kind === "create" ? "Adicionar produto" : route.kind === "edit" ? "Editar produto" : productPreview?.name || "Detalhes do produto"} description={route.kind === "view" ? "Informações, mídias e status do produto." : "Escolha a categoria, inclua mídias e conclua as informações comerciais."} onBack={() => navigate("/products")}>{route.kind === "view" ? (productPreview ? <ProductPreview page product={productPreview} onClose={() => navigate("/products")} onEdit={() => navigate(`/products/${productPreview.id}/edit`)} /> : <ListLoadingSkeleton label="Carregando produto" />) : (productDialog.open ? <ProductEditor page open={productDialog.open} onOpenChange={(open) => { if (!open) navigate("/products"); }} storeId={store.id} categories={categories} onCategoriesChanged={loadCategories} product={productDialog.product} onSaved={async () => { await loadProducts(); navigate("/products"); }} /> : <ListLoadingSkeleton label="Carregando produto" />)}</AdminPagePanel>;

  return <main className="px-5 py-6 sm:px-8 lg:px-12">
    <div className="flex flex-col gap-5 border-b pb-6 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground">Catálogo da loja</p><h1 className="mt-2 text-3xl font-bold tracking-tight sm:text-4xl">Produtos</h1><p className="mt-2 max-w-xl text-sm text-muted-foreground">Organize as mídias, preços e categorias da sua vitrine.</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" disabled={!store?.id} onClick={() => navigate("/products/categories")}><FolderCog className="size-4" />Categorias</Button><Button disabled={!store?.id} onClick={() => navigate("/products/create")}><Plus className="size-4" />Adicionar produto</Button></div></div>
    {!store?.id ? <EmptyStore onCreate={() => navigate("/onboarding/store")} /> : <>
      {shouldShowListControls(result.pagination.total) && <section className="mt-5"><div className="flex gap-2"><div className="relative min-w-0 flex-1"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input value={filters.search} onChange={(event) => changeFilters({ search: event.target.value })} className="pl-9" placeholder="Pesquisar por nome ou descrição" aria-label="Pesquisar produtos" /></div><Button type="button" variant="outline" size="icon" className="shrink-0 md:hidden" aria-label="Exibir filtros" onClick={() => setFiltersOpen((value) => !value)}><SlidersHorizontal className="size-4" /></Button></div><div className={cn("mt-3 gap-3 md:grid md:grid-cols-3", filtersOpen ? "grid" : "hidden")}><label className="flex min-w-0 items-center gap-2 rounded-lg border bg-card px-3 text-sm text-muted-foreground"><span className="sr-only">Data inicial</span><input type="date" className="min-w-0 bg-transparent text-foreground outline-none" value={filters.dateFrom} onChange={(event) => changeFilters({ dateFrom: event.target.value })} /></label><label className="flex min-w-0 items-center gap-2 rounded-lg border bg-card px-3 text-sm text-muted-foreground"><span className="sr-only">Data final</span><input type="date" className="min-w-0 bg-transparent text-foreground outline-none" value={filters.dateTo} onChange={(event) => changeFilters({ dateTo: event.target.value })} /></label><select className="h-10 rounded-lg border bg-card px-3 text-sm font-medium" value={filters.sort} onChange={(event) => changeFilters({ sort: event.target.value })} aria-label="Ordenar produtos"><option value="recent">Mais recentes</option><option value="oldest">Mais antigos</option><option value="name">Nome</option><option value="price_low">Menor preço</option><option value="price_high">Maior preço</option></select></div></section>}
      <section className="mt-5 overflow-hidden rounded-xl border bg-card"><ProductsTable products={result.data} loading={loading} onView={openPreview} onEdit={openEdit} onDelete={setProductToDelete} /></section>
      {shouldShowListControls(result.pagination.total) && <Pagination pagination={result.pagination} onChange={(page) => changeFilters({ page })} limit={filters.limit} onLimit={(limit) => changeFilters({ limit })} />}
    </>}
    {store?.id && <ProductEditor open={productDialog.open} onOpenChange={(open) => { if (!open) navigate("/products"); }} storeId={store.id} categories={categories} onCategoriesChanged={loadCategories} product={productDialog.product} onSaved={async () => { await loadProducts(); navigate("/products"); }} />}
    <ProductPreview product={productPreview} onClose={() => navigate("/products")} onEdit={() => { if (productPreview?.id) navigate(`/products/${productPreview.id}/edit`); }} />
    <AlertDialog open={Boolean(productToDelete)} onOpenChange={(open) => !open && setProductToDelete(null)}><AlertDialogContent><AlertDialogTitle>Excluir produto?</AlertDialogTitle><AlertDialogDescription>“{productToDelete?.name}” e as mídias vinculadas deixarão de aparecer na sua loja. Esta ação não pode ser desfeita.</AlertDialogDescription><div className="mt-6 flex justify-end gap-3"><AlertDialogCancel asChild><Button variant="outline">Cancelar</Button></AlertDialogCancel><AlertDialogAction asChild><Button className="bg-destructive text-destructive-foreground hover:bg-destructive/90" onClick={(event) => { event.preventDefault(); removeProduct(); }}>Excluir</Button></AlertDialogAction></div></AlertDialogContent></AlertDialog>
  </main>;
}

function ProductsTable({ products, loading, onView, onEdit, onDelete }) { if (loading) return <ListLoadingSkeleton label="Carregando produtos" />; if (!products.length) return <div className="p-12 text-center"><span className="mx-auto flex size-12 items-center justify-center rounded-xl bg-muted"><Package className="size-5" /></span><h2 className="mt-4 text-base font-bold">Nenhum produto encontrado</h2><p className="mt-1 text-sm text-muted-foreground">Use “Adicionar produto” para montar a primeira ficha da vitrine.</p></div>; return <><div className="hidden overflow-x-auto md:block"><table className="w-full text-left text-sm"><thead className="border-b bg-muted/35 text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground"><tr><th className="p-4">Produto</th><th className="p-4">Categoria</th><th className="p-4">Preço</th><th className="p-4">Status</th><th className="p-4">Atualizado</th><th className="p-4 text-right">Ações</th></tr></thead><tbody>{products.map((product) => <tr key={product.id} className="border-b last:border-0"><td className="p-4"><ProductIdentity product={product} /></td><td className="p-4 text-muted-foreground">{product.categoryName}</td><td className="p-4 font-semibold">{formatCurrency(product.priceCents)}</td><td className="p-4"><StatusBadge status={product.status} /></td><td className="p-4 text-muted-foreground">{formatDate(product.updatedAt)}</td><td className="p-4"><div className="flex justify-end gap-1"><Button variant="outline" size="icon" onClick={() => onView(product.id)} aria-label={`Visualizar ${product.name}`}><Eye className="size-4" /></Button><Button variant="outline" size="sm" onClick={() => onEdit(product.id)}><Edit3 className="size-3.5" />Editar</Button><Button variant="outline" size="icon" className="text-destructive hover:bg-destructive hover:text-destructive-foreground" onClick={() => onDelete(product)} aria-label={`Excluir ${product.name}`}><Trash2 className="size-4" /></Button></div></td></tr>)}</tbody></table></div><div className="divide-y md:hidden">{products.map((product) => <article className="p-4" key={product.id}><div className="flex gap-3"><ProductIdentity product={product} /><div className="ml-auto flex gap-1"><Button variant="outline" size="icon" onClick={() => onView(product.id)} aria-label={`Visualizar ${product.name}`}><Eye className="size-4" /></Button><Button variant="outline" size="icon" onClick={() => onEdit(product.id)} aria-label={`Editar ${product.name}`}><Edit3 className="size-4" /></Button><Button variant="outline" size="icon" className="text-destructive" onClick={() => onDelete(product)} aria-label={`Excluir ${product.name}`}><Trash2 className="size-4" /></Button></div></div><div className="mt-3 flex items-center justify-between text-sm"><span className="flex items-center gap-2 text-muted-foreground">{product.categoryName}<StatusBadge status={product.status} /></span><strong>{formatCurrency(product.priceCents)}</strong></div></article>)}</div></>; }
function ListLoadingSkeleton({ label }) { return <div className="space-y-4 p-5" aria-label={label}>{[0, 1, 2].map((item) => <div key={item} className="grid grid-cols-[1.6fr_1fr_.7fr_.7fr] gap-4 rounded-xl border p-4"><div className="flex items-center gap-3"><Skeleton className="size-11 rounded-lg" /><span className="flex-1 space-y-2"><Skeleton className="h-4 w-3/4" /><Skeleton className="h-3 w-1/2" /></span></div><Skeleton className="h-5 self-center" /><Skeleton className="h-5 self-center" /><Skeleton className="h-8 self-center" /></div>)}</div>; }
function ProductIdentity({ product }) { return <div className="flex min-w-0 items-center gap-3">{product.mainImageUrl ? <img src={product.mainImageUrl} className="size-11 shrink-0 rounded-lg border object-cover" alt="" /> : <span className="flex size-11 shrink-0 items-center justify-center rounded-lg bg-muted"><ImageIcon className="size-4 text-muted-foreground" /></span>}<span className="min-w-0"><strong className="block truncate font-semibold">{product.name}</strong><small className="mt-0.5 block truncate text-xs text-muted-foreground">{product.sku ? `SKU ${product.sku} · ` : ""}Criado em {formatDate(product.createdAt)}</small></span></div>; }
function StatusBadge({ status }) { const labels = { active: "Ativo", draft: "Rascunho", archived: "Arquivado" }; return <span className={cn("inline-flex rounded-md px-2 py-1 text-[10px] font-bold uppercase tracking-wide", status === "active" ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300" : status === "archived" ? "bg-muted text-muted-foreground" : "bg-amber-500/10 text-amber-700 dark:text-amber-300")}>{labels[status] || "Ativo"}</span>; }
export function ProductPreview({ page = false, product, onClose, onEdit }) { if (!product) return null; const images = product.media.filter((item) => item.kind === "image"); const video = product.media.find((item) => item.kind === "video"); return <ResponsivePanel page={page} open={Boolean(product)} onOpenChange={onClose} title={product.name} description={`${product.categoryName} · ${formatCurrency(product.priceCents)}`} className="max-w-3xl"><div className="min-h-0 flex-1 overflow-y-auto p-5 sm:p-6"><div className="grid gap-5 sm:grid-cols-[minmax(0,1fr)_190px]"><div className="grid grid-cols-2 gap-3">{images.length ? images.map((item) => <img key={item.id} src={item.url} alt={product.name} className="aspect-square w-full rounded-xl border object-cover" />) : <span className="col-span-2 flex aspect-square items-center justify-center rounded-xl bg-muted"><ImageIcon className="size-7 text-muted-foreground" /></span>}</div><div><StatusBadge status={product.status} /><h3 className="mt-4 text-base font-bold">Detalhes</h3>{product.shortDescription && <p className="mt-2 text-sm font-medium text-foreground">{product.shortDescription}</p>}<p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{product.description || "Sem descrição cadastrada."}</p><CatalogSummary product={product} /><p className="mt-4 text-xs text-muted-foreground">Criado em {formatDate(product.createdAt)} · Atualizado em {formatDate(product.updatedAt)}</p>{video && <video className="mt-4 w-full rounded-xl border" src={video.url} controls />}</div></div></div><footer className="flex justify-end gap-2 border-t p-5 sm:px-6"><Button variant="outline" onClick={onClose}>Fechar</Button><Button onClick={onEdit}><Edit3 className="size-4" />Editar produto</Button></footer></ResponsivePanel>; }
function CatalogSummary({ product }) { const logistics = [product.weightGrams ? `${product.weightGrams} g` : "", product.dimensions?.widthMm && product.dimensions?.heightMm && product.dimensions?.depthMm ? `${product.dimensions.widthMm} × ${product.dimensions.heightMm} × ${product.dimensions.depthMm} mm` : ""].filter(Boolean).join(" · "); return <dl className="mt-5 space-y-2 rounded-xl border bg-muted/20 p-3 text-xs"><SummaryRow label="SKU" value={product.sku || "Não informado"} /><SummaryRow label="Marca" value={product.brand || "Não informada"} /><SummaryRow label="Estoque" value={`${product.stockQuantity ?? 0} unidade(s)`} /><SummaryRow label="Preço de origem" value={product.compareAtPriceCents === null || product.compareAtPriceCents === undefined ? "Não informado" : formatCurrency(product.compareAtPriceCents)} /><SummaryRow label="Custo" value={product.costPriceCents === null || product.costPriceCents === undefined ? "Não informado" : formatCurrency(product.costPriceCents)} /><SummaryRow label="Variações" value={`${product.variants?.length ?? product.variantCount ?? 0}`} />{logistics && <SummaryRow label="Logística" value={logistics} />}{product.tags?.length ? <SummaryRow label="Tags" value={product.tags.join(", ")} /> : null}</dl>; }
function SummaryRow({ label, value }) { return <div className="flex gap-3"><dt className="w-24 shrink-0 font-semibold text-muted-foreground">{label}</dt><dd className="min-w-0 break-words text-foreground">{value}</dd></div>; }
function Pagination({ pagination, onChange, limit, onLimit }) { const first = pagination.total ? (pagination.page - 1) * pagination.limit + 1 : 0; const last = Math.min(pagination.total, pagination.page * pagination.limit); return <div className="flex flex-col gap-3 py-5 text-sm sm:flex-row sm:items-center sm:justify-between"><span className="text-muted-foreground">Exibindo {first}–{last} de {pagination.total} produtos</span><div className="flex items-center gap-2"><select className="h-9 rounded-lg border bg-card px-2 text-sm" value={limit} onChange={(event) => onLimit(Number(event.target.value))} aria-label="Itens por página">{PAGE_SIZES.map((size) => <option key={size} value={size}>{size} por página</option>)}</select><Button variant="outline" size="icon" disabled={pagination.page <= 1} onClick={() => onChange(pagination.page - 1)} aria-label="Página anterior"><ArrowLeft className="size-4" /></Button><span className="min-w-14 text-center text-xs font-semibold">{pagination.page} / {pagination.totalPages}</span><Button variant="outline" size="icon" disabled={pagination.page >= pagination.totalPages} onClick={() => onChange(pagination.page + 1)} aria-label="Próxima página"><ArrowRight className="size-4" /></Button></div></div>; }

function CategoryManagerLegacy({ open, route, onOpenChange, onNavigate, storeId, categories, onUpdated }) { const [form, setForm] = useState(null); const [query, setQuery] = useState(""); const [deleting, setDeleting] = useState(null); const [pending, setPending] = useState(false); useEffect(() => { if (!open) return setForm(null); if (route.categoryAction === "create") return setForm({ name: "", description: "", active: true }); if (route.categoryAction === "edit") { const category = categories.find((item) => item.id === route.categoryId); if (category) setForm({ ...category, active: category.active !== false }); } else setForm(null); }, [open, route.key, categories]); const filtered = categories.filter((category) => category.name.toLowerCase().includes(query.toLowerCase())); const save = async (event) => { event.preventDefault(); if (!form) return; setPending(true); try { if (form.id) await api.updateCategory(storeId, form.id, form); else await api.createCategory(storeId, form); toast.success(form.id ? "Categoria atualizada." : "Categoria criada."); await onUpdated(); onNavigate("/products/categories"); } catch (error) { toast.error(error.message); } finally { setPending(false); } }; const remove = async () => { try { await api.deleteCategory(storeId, deleting.id); toast.success("Categoria excluída."); setDeleting(null); await onUpdated(); } catch (error) { toast.error(error.message); } }; return <ResponsivePanel open={open} onOpenChange={onOpenChange} title="Categorias" description="Classifique o catálogo da loja." className="max-w-5xl"><div className="min-h-0 flex-1 overflow-y-auto p-5 sm:p-6"><div className="mb-5 flex gap-2"><div className="relative flex-1"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input className="pl-9" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Pesquisar categoria" /></div><Button onClick={() => onNavigate("/products/categories/create")}><Plus className="size-4" />Nova</Button></div><div className="divide-y rounded-xl border">{filtered.length ? filtered.map((category) => <div className="flex gap-3 p-4" key={category.id}><span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-muted"><Archive className="size-4" /></span><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{category.name}</strong><small className="mt-1 flex flex-wrap items-center gap-1 text-xs text-muted-foreground"><span>{category.productCount} {category.productCount === 1 ? "produto" : "produtos"}{category.description ? ` · ${category.description}` : ""}</span><span className={cn("rounded px-1.5 py-0.5 font-semibold", category.active !== false ? "bg-emerald-500/10 text-emerald-700" : "bg-muted text-muted-foreground")}>{category.active !== false ? "Ativa" : "Inativa"}</span></small></span><Button variant="outline" size="icon" onClick={() => onNavigate(`/products/categories/${category.id}/edit`)} aria-label={`Editar ${category.name}`}><Edit3 className="size-4" /></Button><Button variant="outline" size="icon" className="text-destructive" onClick={() => setDeleting(category)} aria-label={`Excluir ${category.name}`}><Trash2 className="size-4" /></Button></div>) : <div className="p-8 text-center text-sm text-muted-foreground">Nenhuma categoria encontrada.</div>}</div></div>{form && <Dialog open={Boolean(form)} onOpenChange={() => onNavigate("/products/categories")} title={form.id ? "Editar categoria" : "Nova categoria"} description="Crie agrupamentos que ajudam a encontrar produtos rapidamente." className="max-w-lg"><form className="overflow-y-auto p-5 sm:p-6" onSubmit={save}><div className="space-y-2"><Label htmlFor="category-name">Nome</Label><Input id="category-name" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} maxLength="120" required autoFocus /></div><div className="mt-4 space-y-2"><Label htmlFor="category-description">Descrição <span className="text-muted-foreground">(opcional)</span></Label><Textarea id="category-description" value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} maxLength="500" /></div><label className="mt-4 flex items-center justify-between gap-4 rounded-lg border p-3 text-sm font-semibold"><span>Categoria ativa</span><input type="checkbox" checked={form.active !== false} onChange={(event) => setForm({ ...form, active: event.target.checked })} className="size-4 accent-primary" /></label><div className="mt-6 flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => onNavigate("/products/categories")}>Cancelar</Button><Button type="submit" disabled={pending}>{pending && <LoaderCircle className="size-4 animate-spin" />}Salvar categoria</Button></div></form></Dialog>}<AlertDialog open={Boolean(deleting)} onOpenChange={(value) => !value && setDeleting(null)}><AlertDialogContent><AlertDialogTitle>Excluir categoria?</AlertDialogTitle><AlertDialogDescription>{deleting?.productCount ? "Esta categoria possui produtos e não pode ser excluída." : `“${deleting?.name || ""}” será removida do catálogo.`}</AlertDialogDescription><div className="mt-6 flex justify-end gap-3"><AlertDialogCancel asChild><Button variant="outline">Cancelar</Button></AlertDialogCancel><AlertDialogAction asChild><Button disabled={Boolean(deleting?.productCount)} className="bg-destructive text-destructive-foreground" onClick={(event) => { event.preventDefault(); remove(); }}>Excluir</Button></AlertDialogAction></div></AlertDialogContent></AlertDialog></ResponsivePanel>; }

function CategoryManager({ open, route, onOpenChange, onNavigate, storeId, categories, onUpdated }) {
  const [form, setForm] = useState(null); const [query, setQuery] = useState(""); const [deleting, setDeleting] = useState(null); const [pending, setPending] = useState(false);
  useEffect(() => { if (!open) return setForm(null); if (route.categoryAction === "create") return setForm({ name: "", description: "", cardImageUrl: "", heroImageUrl: "", active: true }); const category = categories.find((item) => item.id === route.categoryId); setForm(category ? { ...category, cardImageUrl: category.cardImageUrl || "", heroImageUrl: category.heroImageUrl || "", active: category.active !== false } : null); }, [open, route.key, categories]);
  const save = async (event) => { event.preventDefault(); if (!form) return; setPending(true); try { if (form.id) await api.updateCategory(storeId, form.id, form); else await api.createCategory(storeId, form); toast.success(form.id ? "Categoria atualizada." : "Categoria criada."); await onUpdated(); onNavigate("/products/categories"); } catch (error) { toast.error(error.message); } finally { setPending(false); } };
  const remove = async () => { try { await api.deleteCategory(storeId, deleting.id); toast.success("Categoria excluída."); setDeleting(null); await onUpdated(); } catch (error) { toast.error(error.message); } };
  const filtered = categories.filter((category) => category.name.toLowerCase().includes(query.toLowerCase()));
  return <ResponsivePanel open={open} onOpenChange={onOpenChange} title="Categorias" description="Classifique o catálogo e configure as imagens da vitrine." className="max-w-5xl"><div className="min-h-0 flex-1 overflow-y-auto p-5 sm:p-6"><div className="mb-5 flex gap-2"><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Pesquisar categoria" /><Button type="button" onClick={() => onNavigate("/products/categories/create")}><Plus className="size-4" />Nova</Button></div><div className="divide-y rounded-xl border">{filtered.length ? filtered.map((category) => <div className="flex gap-3 p-4" key={category.id}><span className="flex size-12 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-muted">{category.cardImageUrl ? <img src={category.cardImageUrl} alt="" className="size-full object-cover" /> : <Archive className="size-4" />}</span><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{category.name}</strong><small className="mt-1 block text-xs text-muted-foreground">{category.productCount} produto(s) · card {category.cardImageUrl ? "configurado" : "não configurado"} · capa {category.heroImageUrl ? "configurada" : "não configurada"}</small></span><Button type="button" variant="outline" size="icon" onClick={() => onNavigate(`/products/categories/${category.id}/edit`)} aria-label={`Editar ${category.name}`}><Edit3 className="size-4" /></Button><Button type="button" variant="outline" size="icon" className="text-destructive" onClick={() => setDeleting(category)} aria-label={`Excluir ${category.name}`}><Trash2 className="size-4" /></Button></div>) : <div className="p-8 text-center text-sm text-muted-foreground">Nenhuma categoria encontrada.</div>}</div></div>{form && <Dialog open onOpenChange={() => onNavigate("/products/categories")} title={form.id ? "Editar categoria" : "Nova categoria"} description="Use URLs HTTPS da mídia hospedada para card e capa da vitrine." className="max-w-lg"><form className="space-y-4 overflow-y-auto p-5 sm:p-6" onSubmit={save}><CategoryField label="Nome"><Input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} maxLength="120" required autoFocus /></CategoryField><CategoryField label="Descrição"><Textarea value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} maxLength="500" /></CategoryField><CategoryField label="URL HTTPS da imagem do card"><Input capitalization="none" type="url" value={form.cardImageUrl} onChange={(event) => setForm({ ...form, cardImageUrl: event.target.value })} placeholder="https://.../categoria-card.webp" /></CategoryField><CategoryField label="URL HTTPS da capa"><Input capitalization="none" type="url" value={form.heroImageUrl} onChange={(event) => setForm({ ...form, heroImageUrl: event.target.value })} placeholder="https://.../categoria-capa.webp" /></CategoryField><label className="flex items-center justify-between gap-4 rounded-lg border p-3 text-sm font-semibold"><span>Categoria ativa</span><input type="checkbox" checked={form.active !== false} onChange={(event) => setForm({ ...form, active: event.target.checked })} className="size-4 accent-primary" /></label><div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => onNavigate("/products/categories")}>Cancelar</Button><Button type="submit" disabled={pending}>{pending && <LoaderCircle className="size-4 animate-spin" />}Salvar categoria</Button></div></form></Dialog>}<AlertDialog open={Boolean(deleting)} onOpenChange={(value) => !value && setDeleting(null)}><AlertDialogContent><AlertDialogTitle>Excluir categoria?</AlertDialogTitle><AlertDialogDescription>{deleting?.productCount ? "Esta categoria possui produtos e não pode ser excluída." : `“${deleting?.name || ""}” será removida do catálogo.`}</AlertDialogDescription><div className="mt-6 flex justify-end gap-3"><AlertDialogCancel asChild><Button type="button" variant="outline">Cancelar</Button></AlertDialogCancel><AlertDialogAction asChild><Button type="button" disabled={Boolean(deleting?.productCount)} className="bg-destructive text-destructive-foreground" onClick={(event) => { event.preventDefault(); remove(); }}>Excluir</Button></AlertDialogAction></div></AlertDialogContent></AlertDialog></ResponsivePanel>;
}
function CategoryField({ label, children }) { return <div className="space-y-2"><Label>{label}</Label>{children}</div>; }

export function aspectValue(value) { return value === "9:16" ? 9 / 16 : value === "16:9" ? 16 / 9 : 1; }

function CategoryGate({ open, categories, onSelect, onCancel }) { return <Dialog open={open} onOpenChange={(value) => !value && onCancel()} title="Escolha a categoria" description="A categoria define o formato padrão de recorte das imagens deste produto." className="max-w-md"><div className="space-y-4 p-5 sm:p-6">{categories.filter((category) => category.active !== false).length ? <div className="grid gap-2">{categories.filter((category) => category.active !== false).map((category) => <button key={category.id} type="button" className="flex items-center justify-between rounded-xl border px-4 py-3 text-left text-sm font-semibold transition hover:bg-muted" onClick={() => onSelect(category.id)}><span>{category.name}</span><span className="rounded-md bg-muted px-2 py-1 text-[10px] font-bold">{category.cropAspect || "1:1"}</span></button>)}</div> : <p className="rounded-xl border border-dashed p-5 text-sm text-muted-foreground">Crie uma categoria ativa antes de cadastrar produtos.</p>}<div className="flex justify-end"><Button type="button" variant="outline" onClick={onCancel}>Cancelar</Button></div></div></Dialog>; }

export function ProductEditor({ page = false, open, onOpenChange, storeId, categories, onCategoriesChanged, product, onSaved }) { const { store } = useActiveStore(); const [step, setStep] = useState(1); const [form, setForm] = useState(emptyProductForm); const [draftId, setDraftId] = useState(() => crypto.randomUUID()); const [media, setMedia] = useState([]); const [saving, setSaving] = useState(false); const [cropTarget, setCropTarget] = useState(null); const [categoryQuery, setCategoryQuery] = useState(""); const [categoryMenuOpen, setCategoryMenuOpen] = useState(false); const [creatingCategory, setCreatingCategory] = useState(false); const inputRef = useRef(null); const formRef = useRef(null); const isEditing = Boolean(product?.id); const saveVisible = useContextualSaveVisibility(page && step === 4); const imageLimit = productMediaLimit(store?.planLimits, "productImages", 3); const videoLimit = productMediaLimit(store?.planLimits, "productVideos", 1);
  useEffect(() => { if (!open) return; setStep(1); setDraftId(crypto.randomUUID()); setForm(product ? editorFormFromProduct(product) : emptyProductForm()); setMedia(product ? product.media.map((item) => ({ ...item, localId: item.id, status: "uploaded", uploadId: null, preview: item.url, existing: true })) : []); setCategoryQuery(""); }, [open, product?.id]);
  const pendingMedia = media.filter((item) => !item.existing && item.status === "processing"); const unlinkedMedia = media.some((item) => !item.existing && item.status === "error"); const readyMedia = media.filter((item) => !item.existing && item.status === "ready"); const images = media.filter((item) => item.kind === "image"); const videos = media.filter((item) => item.kind === "video"); const visibleCategories = categories.filter((category) => (category.active !== false || category.id === form.categoryId) && category.name.toLowerCase().includes(categoryQuery.toLowerCase())); const productReady = isProductSaveReady(form);
  useEffect(() => { if (step !== 4 || !formRef.current) return; const formNode = formRef.current; for (const control of formNode.querySelectorAll("input, textarea, select, button")) { if (saving) control.disabled = true; else if (control.type === "submit") control.disabled = unlinkedMedia || !productReady; else control.disabled = false; } formNode.setAttribute("aria-busy", saving ? "true" : "false"); }, [step, saving, unlinkedMedia, productReady, form.name, form.categoryId, form.price]);
  const addFiles = async (files) => { let plannedImages = images.length; let plannedVideos = videos.length; for (const file of Array.from(files)) { const kind = file.type.startsWith("image/") ? "image" : file.type.startsWith("video/") ? "video" : ""; if (!kind) { toast.error("Selecione imagens ou vídeos permitidos."); continue; } if (kind === "image" && plannedImages >= imageLimit) { toast.error(`Você pode adicionar no máximo ${imageLimit} ${imageLimit === 1 ? "foto" : "fotos"}.`); continue; } if (kind === "video" && plannedVideos >= videoLimit) { toast.error(`Você pode adicionar no máximo ${videoLimit} ${videoLimit === 1 ? "vídeo" : "vídeos"}.`); continue; } if (kind === "image") plannedImages += 1; else plannedVideos += 1; const localId = crypto.randomUUID(); const item = { localId, kind, status: "processing", progress: 0, preview: URL.createObjectURL(file), original: file, file: null, uploadId: null, existing: false }; setMedia((current) => [...current, item]); try { const prepared = kind === "image" ? await compressImage(file, { aspect: categoryAspect }) : await compressVideo(file, (progress) => replaceMedia(localId, { progress })); replaceMedia(localId, { status: "ready", file: prepared, progress: 1 }); } catch (error) { replaceMedia(localId, { status: "error", error: error.message }); toast.error(error.message); } } };
  const replaceMedia = (localId, patch) => setMedia((current) => current.map((item) => item.localId === localId ? { ...item, ...patch } : item));
  const removeMedia = async (item) => { try { if (item.existing && product?.id) await api.deleteProductMedia(storeId, product.id, item.id); } catch (error) { toast.error(error.message); return; } if (item.preview?.startsWith("blob:")) URL.revokeObjectURL(item.preview); setMedia((current) => current.filter((entry) => entry.localId !== item.localId)); };
  const next = () => { if (step === 1) { if (!form.categoryId) return toast.error("Escolha a categoria do produto antes de continuar."); if (pendingMedia.length || unlinkedMedia) return toast.error("Aguarde o processamento de todas as mídias antes de continuar."); if (!media.length || !images.length) return toast.error("Adicione pelo menos uma imagem para a vitrine."); } window.requestAnimationFrame(() => setStep((current) => Math.min(4, current + 1))); };
  const quickCreateCategory = async () => { const name = categoryQuery.trim(); if (!name || creatingCategory) return; setCreatingCategory(true); try { const response = await api.createCategory(storeId, { name, description: "", active: true }); setForm((current) => ({ ...current, categoryId: response.category.id })); setCategoryMenuOpen(false); setCategoryQuery(""); await onCategoriesChanged(); toast.success("Categoria criada e selecionada."); } catch (error) { toast.error(error.message); } finally { setCreatingCategory(false); } };
  const save = async (event) => { event.preventDefault(); if (unlinkedMedia || pendingMedia.length) { toast.error("Revise as mídias antes de salvar."); setStep(1); return; } const payload = productPayloadFromForm(form, draftId); if (!payload) { toast.error("Revise preço, estoque, dimensões e variantes antes de salvar."); return; } if (!form.name.trim() || !form.categoryId || payload.priceCents === null) { toast.error("Preencha nome, categoria e preço do produto."); return; } setSaving(true); try { const uploaded = []; for (const item of readyMedia) { const response = await api.uploadProductMedia(storeId, draftId, item.file); uploaded.push(response.media.id); } payload.uploadIds = uploaded; if (isEditing) await api.updateProduct(storeId, product.id, payload); else await api.createProduct(storeId, payload); if (isEditing) toast.success("Produto atualizado."); else if (!maybeCelebrateCreation()) toast.success("Produto criado."); await onSaved(); } catch (error) { toast.error(error.message); } finally { setSaving(false); } };
  const categorySelector = <div className="space-y-2"><Label htmlFor="product-category">Categoria</Label><div className="relative"><Input id="product-category" capitalization="words" className={creatingCategory ? "pr-10" : ""} value={categoryQuery || categories.find((category) => category.id === form.categoryId)?.name || ""} onFocus={() => setCategoryMenuOpen(true)} onChange={(event) => { setCategoryQuery(event.target.value); setForm({ ...form, categoryId: "" }); setCategoryMenuOpen(true); }} placeholder="Pesquisar categoria…" autoComplete="off" />{creatingCategory && <LoaderCircle className="pointer-events-none absolute right-3 top-1/2 size-4 -translate-y-1/2 animate-spin text-muted-foreground" aria-label="Criando categoria" />}{categoryMenuOpen && <div className="absolute z-30 mt-1 w-full overflow-hidden rounded-xl border bg-card shadow-lg">{visibleCategories.map((category) => <button type="button" className="flex w-full items-center justify-between px-3 py-2.5 text-left text-sm hover:bg-muted" key={category.id} onClick={() => { setForm({ ...form, categoryId: category.id }); setCategoryQuery(""); setCategoryMenuOpen(false); }}><span>{category.name}</span><small className="text-xs text-muted-foreground">{category.productCount}</small></button>)}{categoryQuery.trim() && !visibleCategories.some((category) => category.name.toLowerCase() === categoryQuery.trim().toLowerCase()) && <button type="button" disabled={creatingCategory} onClick={quickCreateCategory} className="flex w-full items-center gap-2 border-t px-3 py-3 text-left text-sm font-semibold text-primary hover:bg-muted disabled:cursor-wait disabled:opacity-60">{creatingCategory ? <LoaderCircle className="size-4 animate-spin" /> : <Plus className="size-4" />}Criar categoria: “{categoryQuery.trim()}”</button>}{!visibleCategories.length && !categoryQuery.trim() && <p className="p-3 text-sm text-muted-foreground">Crie a primeira categoria para este catálogo.</p>}</div>}</div></div>;
  const content = <form ref={formRef} onSubmit={save} className="flex min-h-0 flex-1 flex-col"><div className="border-b px-5 py-4 sm:px-6"><StepIndicator active={step} /></div><div className="min-h-0 flex-1 overflow-y-auto p-5 sm:p-6">{step === 1 && <><div className="flex items-start justify-between gap-4"><div><h3 className="font-bold">Categoria, imagens e vídeo</h3><p className="mt-1 text-sm text-muted-foreground">Escolha a categoria para definir o recorte padrão e adicione até {imageLimit} {imageLimit === 1 ? "imagem" : "imagens"} e {videoLimit} {videoLimit === 1 ? "vídeo" : "vídeos"}.</p></div><span className="rounded-md bg-muted px-2 py-1 text-[10px] font-bold uppercase tracking-wide">{images.length}/{imageLimit} fotos · {videos.length}/{videoLimit} {videoLimit === 1 ? "vídeo" : "vídeos"}</span></div><div className="mt-5">{categorySelector}</div><label className={cn("mt-5 flex min-h-36 flex-col items-center justify-center rounded-xl border border-dashed bg-muted/25 p-5 text-center transition-colors", form.categoryId ? "cursor-pointer hover:border-foreground/40 hover:bg-muted/50" : "cursor-not-allowed opacity-60")}><UploadCloud className="size-6 text-muted-foreground" /><strong className="mt-3 text-sm">Selecionar arquivos</strong><span className="mt-1 text-xs text-muted-foreground">JPG, PNG ou WebP até 8 MB; MP4 ou WebM até 45 MB.</span><input ref={inputRef} disabled={!form.categoryId} className="sr-only" type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" onChange={(event) => { addFiles(event.target.files); event.target.value = ""; }} /></label><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{media.map((item) => <MediaCard item={item} key={item.localId} onCrop={() => setCropTarget(item)} onRemove={() => removeMedia(item)} />)}</div>{!media.length && <p className="mt-4 flex items-center gap-2 text-xs text-muted-foreground"><CircleAlert className="size-4" />A primeira imagem será usada como a imagem principal do produto.</p>}</>}{step === 2 && <ProductIdentityStep form={form} setForm={setForm} />}{step === 3 && <ProductSalesStep form={form} setForm={setForm} />}{step === 4 && <ProductDeliveryStep form={form} setForm={setForm} />}</div>{step < 4 ? <footer className="flex justify-between gap-3 border-t p-5 sm:px-6"><Button type="button" variant="outline" onClick={() => step === 1 ? onOpenChange(false) : setStep((current) => current - 1)}>{step === 1 ? "Cancelar" : <><ArrowLeft className="size-4" />Voltar</>}</Button><Button type="button" disabled={step === 1 && (pendingMedia.length > 0 || unlinkedMedia)} onClick={(event) => { event.preventDefault(); next(); }}>{step === 1 && (pendingMedia.length > 0 || unlinkedMedia) && <LoaderCircle className="size-4 animate-spin" />}{step === 1 ? "Enviar mídias e continuar" : "Continuar"}<ArrowRight className="size-4" /></Button></footer> : <ContextualSaveBar visible={page ? saveVisible : true} className="mx-5 mb-5 sm:mx-6 sm:mb-6"><div className="flex flex-col gap-3 rounded-2xl border bg-card/95 p-4 shadow-lg backdrop-blur sm:flex-row sm:items-center sm:justify-between"><p className="text-sm leading-5 text-muted-foreground"><strong className="text-foreground">Quase lá.</strong> Revise as informações de entrega e salve quando estiver pronto.</p><div className="flex gap-2"><Button type="button" variant="outline" onClick={() => setStep(3)}><ArrowLeft className="size-4" />Voltar</Button><Button type="submit" size="lg" disabled={saving || unlinkedMedia}>{saving && <LoaderCircle className="size-4 animate-spin" />}Salvar produto</Button></div></div></ContextualSaveBar>}</form>;
  const categoryAspect = aspectValue(categories.find((category) => category.id === form.categoryId)?.cropAspect);
  return <><ResponsivePanel page={page} open={open} onOpenChange={onOpenChange} title={isEditing ? "Editar produto" : "Adicionar produto"} description={isEditing ? "Atualize a ficha comercial e inclua novas mídias." : "Escolha a categoria e inclua mídias sem sair deste fluxo."} className="max-w-4xl">{content}</ResponsivePanel>{cropTarget && <EasyImageCropper open imageSrc={cropTarget.preview} mediaType={cropTarget.kind} aspect={categoryAspect} title={cropTarget.kind === "video" ? "Recortar vídeo" : "Recortar imagem"} onCancel={() => setCropTarget(null)} onConfirm={async (crop) => { try { replaceMedia(cropTarget.localId, { status: "processing" }); const cropped = cropTarget.kind === "video" ? await compressVideo(cropTarget.original || cropTarget.file, crop, (progress) => replaceMedia(cropTarget.localId, { progress })) : await compressImage(cropTarget.original || cropTarget.file, crop); replaceMedia(cropTarget.localId, { status: "ready", file: cropped, progress: 1, preview: URL.createObjectURL(cropped) }); setCropTarget(null); } catch (error) { replaceMedia(cropTarget.localId, { status: "error", error: error.message }); toast.error(error.message); } }} />}</>;
}

export function productMediaLimit(limits, field, fallback) {
  const configured = Number(limits?.[field]);
  const unlimitedCap = Number(limits?.unlimitedCap);
  if (!Number.isInteger(configured) || configured < 0) return fallback;
  if (configured > 0) return configured;
  return Number.isInteger(unlimitedCap) && unlimitedCap >= 1 ? unlimitedCap : 1000;
}

function MediaCard({ item, onCrop, onRemove }) { return <article className="overflow-hidden rounded-xl border bg-card"><div className="relative aspect-square bg-muted">{item.kind === "image" && item.preview ? <img src={item.preview} alt="Prévia da mídia" className="size-full object-cover" /> : item.kind === "video" && item.preview ? <video className="size-full object-cover" src={item.preview} muted /> : <span className="flex size-full flex-col items-center justify-center text-muted-foreground">{item.kind === "video" ? <Video className="size-6" /> : <ImageIcon className="size-6" />}<small className="mt-2 text-xs">Processando…</small></span>}{item.status === "processing" && <span className="absolute inset-0 flex flex-col items-center justify-center bg-black/45 text-xs font-semibold text-white"><LoaderCircle className="mb-2 size-5 animate-spin" />{item.kind === "video" ? `Comprimindo ${Math.round((item.progress || 0) * 100)}%` : "Comprimindo"}</span>}</div><div className="p-3"><p className={cn("truncate text-xs font-semibold", item.status === "error" && "text-destructive")}>{item.status === "uploaded" ? "✓ Enviada" : item.status === "uploading" ? "Enviando…" : item.status === "ready" ? "✓ Processada" : item.status === "error" ? item.error || "Falha no processamento" : "Processando…"}</p><div className="mt-3 flex gap-2">{!item.existing && item.status !== "processing" && <Button type="button" size="sm" variant="outline" className="flex-1" onClick={onCrop}><Crop className="size-3.5" />Recortar</Button>}<Button type="button" size="sm" variant="outline" className={cn(!item.existing && item.status !== "processing" ? "flex-1" : "w-full", "text-destructive hover:bg-destructive hover:text-destructive-foreground")} onClick={onRemove}><Trash2 className="size-3.5" />Excluir</Button></div></div></article>; }


function ResponsivePanel({ page = false, open, onOpenChange, title, description, children, className }) { return page ? children : <Dialog open={open} onOpenChange={onOpenChange} title={title} description={description} className={className} fullscreen>{children}</Dialog>; }
function ProductIdentityStep({ form, setForm }) { return <div><h3 className="font-bold">Informações do produto</h3><p className="mt-1 text-sm text-muted-foreground">Nome, descrição e dados que ajudam clientes a encontrar o produto.</p><div className="mt-6 grid gap-5"><div className="space-y-2"><Label htmlFor="product-name">Nome</Label><Input id="product-name" capitalization="words" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} maxLength="160" required autoFocus /></div><div className="space-y-2"><Label htmlFor="product-description">Descrição <span className="text-muted-foreground">(opcional)</span></Label><Textarea id="product-description" value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} maxLength="10000" /></div></div><div className="mt-6 border-t pt-6"><ProductCatalogFields form={form} setForm={setForm} section="identity" /></div></div>; }
function ProductSalesStep({ form, setForm }) { return <div><h3 className="font-bold">Preço, estoque e variações</h3><p className="mt-1 text-sm text-muted-foreground">Defina o preço principal e, se necessário, controle promoções, estoque e variações.</p><div className="mt-6 space-y-2"><Label htmlFor="product-price">Preço</Label><Input id="product-price" capitalization="none" inputMode="numeric" placeholder="0,00" value={form.price} onChange={(event) => setForm({ ...form, price: formatCurrencyInput(event.target.value) })} required /></div><div className="mt-6 border-t pt-6"><ProductCatalogFields form={form} setForm={setForm} section="sales" /></div></div>; }
function ProductDeliveryStep({ form, setForm }) { return <div><h3 className="font-bold">Entrega e revisão</h3><p className="mt-1 text-sm text-muted-foreground">Informe peso e dimensões para cálculos de frete mais precisos. Esses campos são opcionais.</p><div className="mt-6 border-t pt-6"><ProductCatalogFields form={form} setForm={setForm} section="logistics" /></div></div>; }
function StepIndicator({ active }) { const steps = [[1, "Mídias"], [2, "Informações"], [3, "Venda"], [4, "Entrega"]]; return <div className="flex flex-wrap items-center gap-2 text-sm">{steps.map(([number, label], index) => <span key={number} className="flex items-center gap-2">{index > 0 && <span className="h-px w-5 border-t border-dashed" />}<Step number={String(number)} label={label} active={active === number} complete={active > number} /></span>)}</div>; }
function Step({ number, label, active, complete }) { return <span className={cn("flex items-center gap-2 font-semibold", active ? "text-foreground" : "text-muted-foreground")}><i className={cn("flex size-6 items-center justify-center rounded-full text-xs not-italic", complete ? "bg-primary text-primary-foreground" : active ? "bg-foreground text-background" : "bg-muted")}>{complete ? <Check className="size-3.5" /> : number}</i>{label}</span>; }
function EmptyStore({ onCreate }) { return <Card className="mx-auto mt-10 max-w-xl"><CardContent className="p-8 text-center"><StoreIcon /><h2 className="mt-4 text-lg font-bold">Crie uma loja antes de cadastrar produtos</h2><p className="mt-2 text-sm text-muted-foreground">O catálogo é sempre vinculado à loja selecionada.</p><Button className="mt-5" onClick={onCreate}><Plus className="size-4" />Criar loja</Button></CardContent></Card>; }
function StoreIcon() { return <span className="mx-auto flex size-12 items-center justify-center rounded-xl bg-muted"><Package className="size-5" /></span>; }
function useMediaQuery(query) { const [matches, setMatches] = useState(() => typeof window !== "undefined" && window.matchMedia(query).matches); useEffect(() => { const media = window.matchMedia(query); const listener = () => setMatches(media.matches); listener(); media.addEventListener("change", listener); return () => media.removeEventListener("change", listener); }, [query]); return matches; }
function normalizeFilters(filters) { return { ...filters, ...dateRangeFromInputs(filters) }; }
export function productRoute(location) { return parseProductManagementRoute(location); }
function formatCurrency(cents) { return formatAdminCurrency(cents); }
function formatDate(timestamp) { return formatAdminDate(timestamp); }
function toCents(value) { return currencyInputToCents(value); }
function emptyProductForm() { return { name: "", description: "", categoryId: "", price: "", sku: "", shortDescription: "", compareAtPrice: "", costPrice: "", brand: "", tags: "", stockQuantity: "0", weightGrams: "", widthMm: "", heightMm: "", depthMm: "", status: "active", variants: [] }; }
